    mutating func update(time: Ticks, fps: Fps) {
        let span = max(clipEnd - clipStart, 0)
        let raw: Ticks
        switch edge {
        case .start: raw = time - clipStart
        case .end: raw = clipEnd - time
        }
    static let minZoom: CGFloat = 0.35
